units.raw_tex:
Consider minimizing a convex objective $\phi$ over an $n\times n$
positive semidefinite matrix $M\succeq0$, as in
\begin{equation}
M^{\star}=\quad\mathrm{minimize}\quad\phi(M)\quad\text{over }\quad M\succeq0,\tag{P}\label{eq:cvx}
\end{equation}
In practice, the matrix order $n$ is often so large---from tens
of thousands to hundreds of millions---that even explicitly forming
the $n^{2}$ elements of the $n\times n$ matrix variable $M$ would
be intractable. Where $r^{\star}=\rank(M^{\star})$ is known a priori
to be small, the standard approach is the nonconvex Burer--Monteiro
factorization~\citep{burer2003nonlinear}, which rewrites $M=XX^{T}$
and then directly optimizes over $X$ using a local optimization algorithm:
\begin{equation}
X^{\star}=\quad\mathrm{minimize}\quad f(X)\eqdef\phi(XX^{T})\text{ where }X\text{ is }n\times r\text{ and }r\ge r^{\star}.\tag{BM}\label{eq:ncvx}
\end{equation}
This way, the semidefinite constraint $M=XX^{T}\succeq0$ is automatically
enforced for free. Moreover, by using a small search rank $r\ll n$,
the number of variables is reduced to $O(n)$. However, this improved
scalability comes at the cost of giving up the convexity of (\ref{eq:cvx}).
In principle, local optimization can fail by getting stuck at a \emph{spurious}
local minimum of (\ref{eq:ncvx})---a local minimum that is strictly
worse than that of the global minimum. In practice, however, there
seems to be many situations where this failure mode does not occur~\citep{candes2015phase,rosen2019se,zhang2019spurious}.

We will establish ``no spurious local minima'' guarantees by showing
that there cannot exist a counterexample that is simultaneously highly
overparameterized, with a large value of $r/r^{\star}$, and also
well-conditioned, with a small value of $\kappa$. 
\begin{definition}
The function $\phi:\S^{n}\to\R$ is said to be a $(\kappa,r,r^{\star})$-\emph{counterexample}
if it satisfies the following:
\begin{itemize}
\item The function $\phi$ is twice-differentiable, $L$-smooth, $\mu$-strongly
convex, and $L/\mu\le\kappa.$
\item The minimizer $M^{\star}=\arg\min_{M\succeq0}\phi(M)$ satisfies $\rank(M^{\star})=r^{\star}\le r$.
\item There exists an $n\times r$ spurious point $X$ with $XX^{T}\ne M^{\star}$
that satisfies $\nabla f(X)=0$ and $\nabla^{2}f(X)\succeq0$ for
$f(U)\eqdef\phi(UU^{T})$. 
\end{itemize}
\end{definition}
For a fixed $r$ and $r^{\star}$, our central claim in \thmref{main}
is that the condition number $\kappa^{\star}$ of the \emph{best-conditioned}
counterexample is exactly determined as 
\begin{equation}
\kappa^{\star}=\inf_{\phi:\S^{n}\to\R}\{\kappa:\phi\text{ is }(\kappa,r,r^{\star})\text{-counterexample}\}=1+2\sqrt{r/r^{\star}}.\label{eq:inf_kappa}
\end{equation}
The sufficient condition follows because there exists no $(\kappa,r,r^{\star})$-counterexample
with $\kappa<1+2\sqrt{r/r^{\star}}$, and so for a fixed $\kappa$,
we can always overparameterize $r/r^{\star}>\frac{1}{4}(\kappa-1)^{2}$
to eliminate all counterexamples. The neccessary condition holds because
a best-conditioned $(\kappa^{\star},r,r^{\star})$-counterexample
does exist.

To prove that $\kappa^{\star}$ is equal to the value stated in (\ref{eq:inf_kappa}),
we proceed by reformulating (\ref{eq:inf_kappa}) into two-stage optimization
problem 
\begin{align*}
\kappa^{\star} & =\inf_{X,Z\in\R^{n\times r}}\{\kappa(X,Z):\rank(Z)=r^{\star},\;XX^{T}\ne ZZ^{T}\}
\end{align*}
in which $\kappa(X,Z)$ corresponds to the best-conditioned counterexample
associated with a \emph{fixed} minimizer $ZZ^{T}$ and a \emph{fixed
}spurious point $X$:
\begin{equation}
\kappa(X,Z)=\inf_{\begin{subarray}{c}
\phi:\S^{n}\to\R\end{subarray}}\left\{ \kappa:\begin{array}{c}
\phi\text{ is }1\text{-strongly convex and }\kappa\text{-smooth,}\\
ZZ^{T}=\arg\min_{M\succeq0}\phi(M),\\
\nabla f(X)=0,\;\nabla^{2}f(X)\succeq0\text{ where }f(U)\eqdef\phi(UU^{T}).
\end{array}\right\} \label{eq:mu_reform}
\end{equation}
This two-stage reformulation is inspired by \citet{zhang2018much,zhang2019sharp},
who showed for a fixed $X,Z$ that finding the best-conditioned \emph{quadratic}
counterexample $\phi$ that satisfies $\nabla\phi(ZZ^{T})=0$ can
be exactly posed as a standard-form \emph{semidefinite program} or
SDP. Our proof extends this SDP formulation to a nonquadratic $\phi$
with a possibly nonzero $\nabla\phi(ZZ^{T})\succeq0$ at optimality
by introducing a slack variable.

\begin{remark}
The definition of $\beta$ becomes ambiguous when $Z_{\perp}=0$.
This is without loss of precision, because $Z_{\perp}=0$ implies
$\alpha=0$, and therefore $\kappa_{\lb}(X,Z)=1$ regardless of the
value of $\beta$. 
\end{remark}

Our proof of \thmref{EckartYoung} follows a trace inequality of Ruhe~\citep{ruhe1970perturbation}
(see also \citep[Chapter~9]{marshall2011inequalities}).\footnote{This simplified proof via Ruhe's inequality is due to an anonymous
reviewer.} The inequality states that, for $n\times n$ positive semidefinite
matrices $A,B$, we have
\begin{equation}
\sum_{i=1}^{n}\lambda_{i}(A)\lambda_{n-i+1}(B)\le\inner AB\le\sum_{i=1}^{n}\lambda_{i}(A)\lambda_{i}(B)\label{eq:Ruhe}
\end{equation}
where the eigenvalues are ordered $\lambda_{1}(A)\ge\cdots\ge\lambda_{n}(A)$
and $\lambda_{1}(B)\ge\cdots\ge\lambda_{n}(B)$.

\begin{equation}
\J_{X}\vect(V)=\vect(XV^{T}+VX^{T}),\qquad\J_{X}^{T}\vect(M)=\vect((M+M^{T})X)\label{eq:Jxdef}
\end{equation}

\begin{equation}
\mat((I-\J_{X}\J_{X}^{\dagger})\e)=(I-XX^{\dagger})(XX^{T}-ZZ^{T})(I-XX^{\dagger})=-Z_{\perp}Z_{\perp}^{T}\label{eq:e2}
\end{equation}

\begin{claim}
Let $W=\sum_{j=1}^{m}\vect(V_{j})\vect(V_{j})^{T}$ where $V_{1},\dots,V_{m}\in\R^{n\times r}$.
Partition $W$ into $r\times r$ blocks of $n\times n$, as in $W=[W_{i,j}]_{i,j=1}^{r}$
for $W_{i,j}\in\R^{n\times n}$. Then, 
\[
\sum_{i=1}^{r}W_{i,i}=\sum_{j=1}^{m}V_{j}V_{j}^{T},\qquad\inner{\J_{X}^{T}\J_{X}}W=\sum_{j=1}^{m}\|XV_{j}^{T}+V_{j}X^{T}\|_{F}^{2}.
\]
\end{claim}

\begin{gather}
\sum_{i=1}^{r}W_{i,i}=\gamma_{2}\cdot\sum_{j=1}^{r}Z_{\perp}e_{i}v_{r}^{T}v_{r}e_{i}^{T}Z_{\perp}^{T}=\gamma_{2}\cdot Z_{\perp}\left(\sum_{i=1}^{r}e_{i}e_{i}^{T}\right)Z_{\perp}^{T}=\gamma_{2}\cdot Z_{\perp}Z_{\perp}^{T}.\label{eq:Wsol1}
\end{gather}

\begin{align}
\langle\J_{X}^{T}\J_{X},W\rangle & =\gamma_{2}\cdot\sum_{i=1}^{m}\|\J_{X}\vect(Z_{\perp}e_{i}v_{r}^{T})\|^{2}=\gamma_{2}\cdot\sum_{i=1}^{m}\|Xv_{r}e_{i}^{T}Z_{\perp}^{T}+Z_{\perp}e_{i}v_{r}^{T}X^{T}\|_{F}^{2}\nonumber \\
 & =\gamma_{2}\cdot\sum_{i=1}^{m}2\|Z_{\perp}e_{i}v_{r}^{T}X^{T}\|_{F}^{2}=2\gamma_{2}\cdot\lambda_{\min}(X^{T}X)\|Z_{\perp}\|_{F}^{2}\label{eq:Wsol2}
\end{align}

Finally, we give a constructive proof for the heuristic upper-bound
in \lemref{heuristic}. First, recall from \lemref{sdp_formu} that
our SDP upper-bound is defined as the following
\begin{equation}
\kappa_{\ub}(X,Z)=\min_{\kappa,\H}\left\{ \kappa:I\preceq\H\preceq\kappa I,\:\J_{X}^{T}\H\e=0,\;-2I_{r}\otimes\mat(\H\e)\preceq\J_{X}^{T}\H\J_{X}\right\} \label{eq:kappaub_prob}
\end{equation}
where $\e=\vect(XX^{T}-ZZ^{T})$ and its Jacobian $\J_{X}$ is defined
to satisfy $\J_{X}\vect(V)=\vect(XV^{T}+VX^{T})$ for all $V$. Below,
we derive a set of sufficient conditions for a given $(\kappa,\H)$
to be feasible for (\ref{eq:kappaub_prob}).

