\begin{lemma}[SDP formulation]
\label{lem:sdp_formu}Define $\kappa(X,Z)$ as in (\ref{eq:mu_reform}).
We have $\kappa_{\ub}(X,Z)\ge\kappa(X,Z)\ge\kappa_{\lb}(X,Z)$ where
\begin{gather*}
\kappa_{\ub}(X,Z)\eqdef\min_{\kappa,\H}\left\{ \kappa:I\preceq\H\preceq\kappa I,\;\J_{X}^{T}\H\e=0,\;-2I_{r}\otimes\mat(\H\e)\preceq\J_{X}^{T}\H\J_{X}\right\} \\
\kappa_{\lb}(X,Z)\eqdef\min_{\kappa,s,\H}\left\{ \kappa:\begin{array}{c}
I\preceq\H\preceq\kappa I,\quad\mat(s)\succeq0,\quad\J_{Z}^{T}s=0,\\
\J_{X}^{T}(\H\e+s)=0,\quad-2I_{r}\otimes\mat(\H\e+s)\preceq\kappa\J_{X}^{T}\J_{X}
\end{array}\right\} 
\end{gather*}
and $\e=\vect(XX^{T}-ZZ^{T})$ and $\J_{U}\vect(V)=\vect(UV^{T}+VU^{T})$
for all $V$.
\end{lemma}

\begin{proof}
Denote $S_{M}$ as the convex gradient $\nabla\phi(M)$ evaluated
at $M$, and denote $\H_{M}$ as the matrix representation of the
convex Hessian operator $\nabla^{2}\phi(M)$ evaluated at $M$. It
follows from $\inner{\nabla^{2}\phi(M)[E]}E=\vect(E)^{T}\H_{M}\vect(E)$
that: 
\begin{equation}
\phi\text{ is }1\text{-strongly convex and }\kappa\text{-smooth}\iff I\preceq\H_{M}\preceq\kappa I\quad\text{for all }M\in\S^{n}.\label{eq:cond}
\end{equation}
Additionally, the Karush--Kuhn--Tucker conditions at $M^{\star}=ZZ^{T}$
read:
\begin{equation}
ZZ^{T}=\arg\min_{M\succeq0}\phi(M)\quad\iff\quad S_{ZZ^{T}}\succeq0,\quad S_{ZZ^{T}}Z=0.\label{eq:kktZZ}
\end{equation}
Note that strong duality holds in the above because $ZZ^{T}+\epsilon I$
is a strictly feasible point with a bounded objective due to $\kappa$-smoothness.
Next, we observe that the two gradient evaluations $S_{XX^{T}}$ and
$S_{ZZ^{T}}$ are related via the fundamental theorem of calculus:
\begin{gather*}
\nabla\phi(XX^{T})=\nabla\phi(ZZ^{T})+\int_{0}^{1}\nabla^{2}\phi((1-t)ZZ^{T}+tXX^{T})[XX^{T}-ZZ^{T}]\,\d t\\
\iff\quad\vect(S_{XX^{T}})=\vect(S_{ZZ^{T}})+\left[\int_{0}^{1}\H_{M(t)}\,\d t\right]\vect(XX^{T}-ZZ^{T}).
\end{gather*}
Denoting $s=\vect(S_{ZZ^{T}})$ and $\H_{\av}=\int_{0}^{1}\H_{M(t)}\,\d t$
and $\e=\vect(XX^{T}-ZZ^{T})$ allows us to rewrite the directional
derivatives of $f(U)\eqdef\phi(UU^{T})$ as follows: 
\begin{align}
\inner{\nabla f(X)}V & =\vect(V)^{T}\J_{X}^{T}(\H_{\av}\e+s),\nonumber \\
\inner{\nabla^{2}f(X)[V]}V & =\vect(V)^{T}[2I_{r}\otimes\mat(\H_{\av}\e+s)+\J_{X}^{T}\H_{XX^{T}}\J_{X}]\,\vect(V).\label{eq:vecdf}
\end{align}
Substituting (\ref{eq:cond}), (\ref{eq:vecdf}), and (\ref{eq:kktZZ})
into (\ref{eq:mu_reform}) yields exactly
\begin{equation}
\kappa(X,Z)=\inf_{\kappa,\phi:\S^{n}\to\R}\left\{ \kappa:\begin{array}{c}
I\preceq\H_{M}\preceq\kappa I\quad\text{for all }M\in\S^{n},\\
\mat(s)\succeq0,\quad\J_{Z}^{T}s=0,\quad\J_{X}^{T}(\H_{\av}\e+s)=0,\\
-2I_{r}\otimes\mat(\H_{\av}\e+s)\preceq\J_{X}^{T}\H_{XX^{T}}\J_{X}.
\end{array}\right\} \label{eq:kappa_sdp1}
\end{equation}
We obtain the upper-bound $\kappa_{\ub}(X,Z)$ from $\kappa(X,Z)$
in  (\ref{eq:kappa_sdp1}) by fixing $\H_{M}\equiv\H$ for all $M$,
and $S_{ZZ^{T}}\equiv\mat(s)=0$. We obtain the lower-bound $\kappa_{\lb}(X,Z)$
from $\kappa(X,Z)$ in (\ref{eq:kappa_sdp1}) by substituting the
relaxation 
\[
-2I_{r}\otimes\mat(\H_{\av}\e+s)\quad\preceq\quad\J_{X}^{T}\H_{XX^{T}}\J_{X}\quad\preceq\quad\kappa\cdot\J_{X}^{T}\J_{X},
\]
in order to avoid explicitly optimizing over $\H_{XX^{T}}$:
\begin{align}
\kappa(X,Z) & \ge\inf_{\kappa,\phi:\S^{n}\to\R}\left\{ \kappa:\begin{array}{c}
I\preceq\H_{M}\preceq\kappa I\quad\text{for all }M\in\S^{n},\\
\mat(s)\succeq0,\quad\J_{Z}^{T}s=0,\quad\J_{X}^{T}(\H_{\av}\e+s)=0,\\
-2I_{r}\otimes\mat(\H_{\av}\e+s)\preceq\kappa\cdot\J_{X}^{T}\J_{X}.
\end{array}\right\} \label{eq:kappasdp2}
\end{align}
Finally, we impose $I\preceq\H_{M}\preceq\kappa I$ over the average
Hessian $\H_{\av}=\int_{0}^{1}\H_{M(t)}\,\d t$ and then relax this
constraint over $\H_{M}$ for all other values of $M$.\qed
\end{proof}

\begin{lemma}[Closed-form lower-bound]
\label{lem:abdef}For $X,Z\in\R^{n\times r}$ such that $XX^{T}\ne ZZ^{T}$,
let $Z_{\perp}=(I-XX^{\dagger})Z$. We have
\begin{gather*}
\kappa_{\lb}(X,Z)\ge\begin{cases}
{\displaystyle \frac{1+\sqrt{1-\alpha^{2}}}{1-\sqrt{1-\alpha^{2}}}} & \text{if }\beta\ge{\displaystyle \frac{\alpha}{1+\sqrt{1-\alpha^{2}}}},\\
{\displaystyle \frac{1-\alpha\beta}{(\alpha-\beta)\beta}} & \text{if }\beta\le{\displaystyle \frac{\alpha}{1+\sqrt{1-\alpha^{2}}}},
\end{cases}\\
\text{ where }\qquad\alpha=\frac{\|Z_{\perp}Z_{\perp}^{T}\|_{F}}{\|XX^{T}-ZZ^{T}\|_{F}},\qquad\beta=\frac{\lambda_{\min}(X^{T}X)}{\|XX^{T}-ZZ^{T}\|_{F}}{\displaystyle \frac{\tr(Z_{\perp}Z_{\perp}^{T})}{\|Z_{\perp}Z_{\perp}^{T}\|_{F}}}.
\end{gather*}
\end{lemma}

\begin{theorem}[Regularized Eckart--Young]
\label{thm:EckartYoung}Given $A\in\S_{+}^{n}$ and $B\in\S_{+}^{r}$
with $r\le n$, let $A=\sum_{i=1}^{n}s_{i}u_{i}u_{i}^{T}$ and $B=\sum_{i=1}^{r}d_{i}v_{i}v_{i}^{T}$
denote the usual orthonormal eigendecompositions with $s_{1}\ge\cdots\ge s_{n}\ge0$
and $0\le d_{1}\le\cdots\le d_{r}.$ Then, 
\begin{align}
\min_{Y\in\R^{n\times r}}\left\{ \|A-YY^{T}\|_{F}^{2}+2\langle B,Y^{T}Y\rangle\right\}  & =\sum_{i=1}^{n}s_{i}^{2}-\sum_{i=1}^{r}[(s_{i}-d_{i})_{+}]^{2}\label{eq:ey-sol}
\end{align}
with minimizer $Y^{\star}=\sum_{i=1}^{r}u_{i}v_{i}^{T}\sqrt{(s_{i}-d_{i})_{+}}$
where $(\cdot)_{+}\eqdef\max\{0,\cdot\}$. 
\end{theorem}

\begin{proof}
[\thmref{EckartYoung}]Recall that $A=\sum_{i=1}^{n}s_{i}u_{i}u_{i}^{T}$
and $B=\sum_{i=1}^{r}d_{i}v_{i}v_{i}^{T}$ with $s_{1}\ge\cdots\ge s_{n}\ge0$
and $0\le d_{1}\le\cdots\le d_{r}.$ It follows from (\ref{eq:Ruhe})
that
\begin{gather*}
\inner A{YY^{T}}\le\sum_{i=1}^{n}\lambda_{i}(YY^{T})\cdot\lambda_{i}(A)=\sum_{i=1}^{r}s_{i}\sigma_{i}^{2}(Y),\\
\inner B{Y^{T}Y}\ge\sum_{i=1}^{r}\lambda_{i}(Y^{T}Y)\cdot\lambda_{n-i+1}(B)=\sum_{i=1}^{r}d_{i}\sigma_{i}^{2}(Y).
\end{gather*}
Substituting yields the following lower-bound, which is valid for
all choices of $Y$:
\begin{align*}
\|A-YY^{T}\|_{F}^{2}+2\inner B{Y^{T}Y}= & \|A\|_{F}^{2}+\|YY^{T}\|_{F}^{2}-2\inner A{YY^{T}}+2\inner B{Y^{T}Y}\\
\ge & \sum_{i=1}^{n}s_{i}^{2}+\sum_{i=1}^{r}\sigma_{i}^{4}(Y)-2\sum_{i=1}^{r}s_{i}\sigma_{i}^{2}(Y)+2\sum_{i=1}^{r}d_{i}\sigma_{i}^{2}(Y)\\
\ge & \sum_{i=1}^{n}s_{i}^{2}-\sum_{i=1}^{r}[(s_{i}-d_{i})_{+}]^{2}.
\end{align*}
The final line applied the following result as a lower-bound:
\begin{align*}
\sigma_{i}^{4}(Y)-2(s_{i}-d_{i})\sigma_{i}^{2}(Y)\ge & \min_{x_{i}\ge0}x_{i}^{2}-2(s_{i}-d_{i})x_{i}\\
= & \min_{x_{i}\ge0}[x_{i}-(s_{i}-d_{i})]^{2}-(s_{i}-d_{i})^{2}\\
= & [(s_{i}-d_{i})_{+}-(s_{i}-d_{i})]^{2}-(s_{i}-d_{i})^{2}=-[(s_{i}-d_{i})_{+}]^{2}.
\end{align*}
Finally, we verify that $Y^{\star}=\sum_{i=1}^{n}u_{i}v_{i}\sqrt{(s_{i}-d_{i})_{+}}$
attains the lower-bound derived above. \qed
\end{proof}

\begin{lemma}
\label{lem:numcard}If $x\ge0$ and $\one^{T}x\le\|x\|^{2}$, then
$\one^{T}\left(I-xx^{T}/\|x\|^{2}\right)\one\ge\|(\one-x)_{+}\|^{2}$.
\end{lemma}

\begin{lemma}
\label{lem:keyclaim}Given $s,d\in\R_{+}^{n}$, let $s_{i}\ge s_{\lb}\ge0$
for all $i$. Then we have
\begin{align*}
\|s\|^{2}-\|(s-d)_{+}\|^{2}\ge & \begin{cases}
s_{\lb}^{2}\frac{(\one^{T}d)^{2}}{\|d\|^{2}} & \text{if }s_{\lb}\one^{T}d\le\|d\|^{2},\\
2s_{\lb}\one^{T}d-\|d\|^{2} & \text{if }s_{\lb}\one^{T}d\ge\|d\|^{2}.
\end{cases}
\end{align*}
\end{lemma}

\begin{proof}
First, we observe that $\psi(t)\equiv t^{2}-[(t-\alpha)_{+}]^{2}$
is an increasing function of $t\ge0$. It follows from element-wise
monotonicity that
\[
\|s\|^{2}-\|(s-d)_{+}\|^{2}\ge\|s_{\lb}\one\|^{2}-\|(s_{\lb}\one-d)_{+}\|^{2}=s_{\lb}^{2}\left(\|\one\|^{2}-\|(\one-d/s_{\lb})_{+}\|^{2}\right)
\]
If $s_{\lb}\one^{T}d\le\|d\|^{2}$, then write $x=d/s_{\lb}\ge0$,
and observe that $\one^{T}x\le\|x\|^{2}$ holds. Therefore, applying
\lemref{numcard} yields
\begin{align*}
s_{\lb}^{2}\left(\|\one\|^{2}-\|(\one-d/s_{\lb})_{+}\|^{2}\right) & =s_{\lb}^{2}\left(\|\one\|^{2}-\|(\one-x)_{+}\|^{2}\right)\ge s_{\lb}^{2}\one^{T}\left(xx^{T}/\|x\|^{2}\right)\one\\
 & =s_{\lb}^{2}\left([\one^{T}(d/s_{\lb})]^{2}/\|d/s_{\lb}\|^{2}\right)=s_{\lb}^{2}(\one^{T}d)^{2}/\|d\|^{2}.
\end{align*}
If otherwise $s_{\lb}\one^{T}d\ge\|d\|^{2}$, then we have 
\begin{align*}
s_{\lb}^{2}\left(\|\one\|^{2}-\|(\one-d/s_{\lb})_{+}\|^{2}\right)\ge s_{\lb}^{2}\left(\|\one\|^{2}-\|\one-d/s_{\lb}\|^{2}\right)=2s_{\lb}\one^{T}d-\|d\|^{2}.
\end{align*}
\qed
\end{proof}

\begin{proof}
The two parameters $\alpha$ and $\beta$ are unitarily invariant
with respect to $X,Z$, so we may assume without loss of generality
that $X,Z$ are partitioned as
\[
X=\begin{bmatrix}X_{1}\\
0
\end{bmatrix}\qquad Z=\begin{bmatrix}Z_{1}\\
Z_{2}
\end{bmatrix}\qquad\text{where }X_{1}\in\R^{r\times r},\;Z_{1}\in\R^{r\times p},\;Z_{2}\in\R^{(n-r)\times p}.
\]
(Otherwise, take the QR decomposition $X=QR$ and note that $\alpha,\beta$
remain unchanged with $X\gets Q^{T}X$ and $Z\gets Q^{T}Z$.) Denote
$s\in\R^{r}$ as the $r$ eigenvalues of $X_{1}X_{1}^{T}$ and $d\in\R^{p}$
as the $p$ eigenvalues of $Z_{2}^{T}Z_{2}$ 
\begin{align*}
s_{i}\eqdef & \lambda_{i}(X_{1}X_{1}^{T})=\lambda_{i}(XX^{T}),\quad s_{1}\ge s_{2}\ge\cdots\ge s_{r}\ge0,\\
d_{i}\eqdef & \lambda_{i}(Z_{2}^{T}Z_{2})=\lambda_{i}(Z_{\perp}Z_{\perp}^{T}),\quad0\le d_{1}\le d_{2}\le\cdots\le d_{p}.
\end{align*}
Writing $\e=\vect(XX^{T}-ZZ^{T})$ yields
\begin{align*}
\alpha & =\frac{\|Z_{2}Z_{2}^{T}\|_{F}}{\|XX^{T}-ZZ^{T}\|_{F}}=\frac{\|d\|_{F}}{\|\e\|_{F}}, & \beta & =\frac{\lambda_{\min}(X_{1}^{T}X_{1})}{\|XX^{T}-ZZ^{T}\|_{F}}\cdot\frac{\tr(Z_{2}Z_{2}^{T})}{\|Z_{2}Z_{2}^{T}\|_{F}}=\frac{s_{r}\cdot\one^{T}d}{\|\e\|\|d\|}.
\end{align*}
We expand $\|XX^{T}-ZZ^{T}\|_{F}^{2}$ block-wise and evoke our Regularized
Eckart--Young Theorem (\thmref{EckartYoung}) over the $r\times p$
matrix block $Z_{1}$:
\begin{align*}
\|XX^{T}-ZZ^{T}\|_{F}^{2} & =\|X_{1}X_{1}^{T}-Z_{1}Z_{1}^{T}\|_{F}^{2}+2\langle Z_{2}^{T}Z_{2},Z_{1}^{T}Z_{1}\rangle+\|Z_{2}Z_{2}^{T}\|^{2}\\
 & \ge\min_{Z_{1}\in\R^{r\times p}}\{\|X_{1}X_{1}^{T}-Z_{1}Z_{1}^{T}\|_{F}^{2}+2\langle Z_{2}^{T}Z_{2},Z_{1}^{T}Z_{1}\rangle\}+\|Z_{2}Z_{2}^{T}\|^{2}\\
 & =\|s\|^{2}-\|(s'-d)_{+}\|^{2}+\|d\|^{2}
\end{align*}
where $s'=(s_{1},s_{2},\dots,s_{p})$. Now, evoking our technical
lemma (\lemref{keyclaim}) with $s_{\lb}\equiv s_{r}$ yields the
following two lower-bounds on $\|XX^{T}-ZZ^{T}\|_{F}^{2}=\|\e\|^{2}$:\begin{subequations}\label{eq:key-claim}
\begin{gather}
s_{r}\one^{T}d\le\|d\|^{2}\quad\implies\quad\|\e\|^{2}\ge s_{r}^{2}\frac{(\one^{T}d)^{2}}{\|d\|^{2}}+(r-p)s_{r}^{2}+\|d\|^{2},\label{eq:key-claim1}\\
s_{r}\one^{T}d\ge\|d\|^{2}\quad\implies\quad\|\e\|^{2}\ge2s_{r}\one^{T}d-\|d\|^{2}+(r-p)s_{r}^{2}+\|d\|^{2}.\label{eq:key-claim2}
\end{gather}
\end{subequations}Substituting $s_{r}=\beta\cdot\|\e\|\|d\|/(\one^{T}d)$
yields
\[
(r-p)s_{r}^{2}=(r-p)\frac{\|d\|^{2}}{(\one^{T}d)^{2}}\beta^{2}\|\e\|^{2}\ge(r-p)\frac{1}{\nnz(d)}\beta^{2}\|\e\|^{2}\ge\frac{(r-p)}{p}\beta^{2}\|\e\|^{2},
\]
and substituting into (\ref{eq:key-claim}) yields\begin{subequations}
\begin{gather}
\beta\le\alpha\quad\implies\quad1\ge\beta^{2}+\alpha^{2}+\frac{(r-p)}{p}\beta^{2}=\alpha^{2}+\frac{r}{p}\beta^{2},\label{eq:key-claim3}\\
\beta\ge\alpha\quad\implies\quad1\ge2\alpha\beta+\frac{(r-p)}{p}\beta^{2}=\alpha^{2}+\frac{r}{p}\beta^{2}-(\beta-\alpha)^{2},\label{eq:key-claim4}
\end{gather}
\end{subequations}as desired. \qed
\end{proof}

\begin{lemma}
\label{lem:I-JJ+}For any $X\in\R^{n\times r}$, the matrix $\J_{X}$
defined in (\ref{eq:Jxdef}) satisfies $I-\J_{X}\J_{X}^{\dagger}=(I-XX^{\dagger})\otimes(I-XX^{\dagger})$
where $\dagger$ denotes the pseudoinverse. 
\end{lemma}

\begin{lemma}
\label{lem:tradeoff}We have
\[
\kappa_{\lb}(X,Z)=\max_{t\ge0}\frac{1+\cos\theta(t)}{2t+1-\cos\theta(t)}
\]
where $\cos\theta(t)$ is defined as follows
\begin{equation}
\cos\theta(t)=\max_{y,W_{i,j}}\left\{ \e^{T}\f:\begin{array}{c}
\f\equiv\J_{X}y-\sum_{i=1}^{r}\vect(W_{i,i}),\quad\|\e\|\|\f\|=1,\\
(I-ZZ^{\dagger})\,\mat(\f)\,(I-ZZ^{\dagger})\succeq0,\\
\langle\J_{X}^{T}\J_{X},W\rangle=2t,\quad W=[W_{i,j}]_{i,j=1}^{r}\succeq0,
\end{array}\right\} \label{eq:cosprob}
\end{equation}
with respect to $y\in\R^{nr}$ and $W_{i,j}\in\R^{n\times n}$ for
$i,j\in\{1,2,\dots,r\}$.
\end{lemma}

\begin{lemma}
\label{lem:costheta}We have $\cos\theta(t)\ge\alpha\cdot(t/\beta)+\sqrt{1-\alpha^{2}}\sqrt{1-t^{2}/\beta^{2}}$
for $0\le t\le\alpha\beta$ where $Z_{\perp}=(I-XX^{\dagger})Z$ and
\begin{align*}
\alpha & =\frac{\|Z_{\perp}Z_{\perp}^{T}\|_{F}}{\|XX^{T}-ZZ^{T}\|_{F}}, & \beta & =\frac{\lambda_{\min}(X^{T}X)\cdot\tr(Z_{\perp}Z_{\perp}^{T})}{\|XX^{T}-ZZ^{T}\|_{F}\|Z_{\perp}Z_{\perp}^{T}\|_{F}}.
\end{align*}
\end{lemma}

\begin{proof}
Write $\rho\equiv\sqrt{r/r^{\star}}$, and take $[Q_{1},Q_{2}]=I_{r+r^{\star}}$
without loss of generality. Decomposing $\e=\vect(XX^{T}-ZZ^{T})$
into eigenvectors and applying $\H$ yields
\begin{gather*}
\mat(\e)=\begin{bmatrix}I_{r} & 0\\
0 & -(1+\rho)I_{r^{\star}}
\end{bmatrix}=-\frac{1}{2\rho}\begin{bmatrix}I_{r} & 0\\
0 & \rho I_{r^{\star}}
\end{bmatrix}+\frac{1+2\rho}{2\rho}\begin{bmatrix}I_{r} & 0\\
0 & -\rho I_{r^{\star}}
\end{bmatrix},\\
\mat(\H\e)=-\frac{1+2\rho}{2\rho}\begin{bmatrix}I_{r} & 0\\
0 & \rho I_{r^{\star}}
\end{bmatrix}+\frac{1+2\rho}{2\rho}\begin{bmatrix}I_{r} & 0\\
0 & -\rho I_{r^{\star}}
\end{bmatrix}=\begin{bmatrix}0_{r} & 0\\
0 & -\kappa I_{r^{\star}}
\end{bmatrix}.
\end{gather*}
Clearly, $\inner{\mat(\e)}{\mat(\H\e)}=\kappa(1+\rho)r^{\star}.$
For $v=\vect(V)=\vect([V_{1};V_{2}])$ with $V_{1}\in\R^{r\times r}$
and $V_{2}\in\R^{r^{\star}\times r}$, observe that 
\begin{gather*}
v^{T}\J_{X}\H\e=\left\langle \begin{bmatrix}V_{1}+V_{1}^{T} & V_{2}^{T}\\
V_{2} & 0_{r^{\star}}
\end{bmatrix},\begin{bmatrix}0_{r} & 0\\
0 & -\kappa I_{r^{\star}}
\end{bmatrix}\right\rangle =0,\\
v^{T}[I_{r}\otimes\mat(\H\e)]v=\langle\mat(\H\e),VV^{T}\rangle=\left\langle \begin{bmatrix}0_{r} & 0\\
0 & -\kappa I_{r^{\star}}
\end{bmatrix},\begin{bmatrix}V_{1}V_{1}^{T} & V_{1}V_{2}^{T}\\
V_{2}V_{1}^{T} & V_{2}V_{2}^{T}
\end{bmatrix}\right\rangle =-\kappa\|V_{2}\|^{2},\\
v^{T}\J_{X}^{T}\H\J_{X}v=\left\Vert \H^{1/2}\vect\left(\begin{bmatrix}V_{1}+V_{1}^{T} & V_{2}^{T}\\
V_{2} & 0_{r^{\star}}
\end{bmatrix}\right)\right\Vert ^{2}\ge\left\Vert \H^{1/2}\vect\left(\begin{bmatrix}0_{r} & V_{2}^{T}\\
V_{2} & 0_{r^{\star}}
\end{bmatrix}\right)\right\Vert ^{2}=2\kappa\|V_{2}\|^{2}.
\end{gather*}
Therefore, $v^{T}\J_{X}\H\e=0$ and $2v^{T}[I_{r}\otimes\mat(\H\e)]v\ge-v^{T}\J_{X}^{T}\H\J_{X}v$
hold for all $v$. \qed
\end{proof}

\section{\label{app:tradeoff}Derivation of the dual for the lower-bound problem
(Proof of \lemref{tradeoff})}

We will derive the Lagrangian dual for the following
\begin{align*}
\kappa_{\lb}(X,Z) & =\min_{\kappa,\H,s}\left\{ \kappa:\begin{array}{c}
I\preceq\H\preceq\kappa I,\qquad\J_{Z}^{T}s=0,\qquad s\in\vect(\S_{+}^{n}),\\
\J_{X}^{T}(\H\e+s)=0,\quad2I_{r}\otimes\mat(\H\e+s)+\kappa\J_{X}^{T}\J_{X}\succeq0.
\end{array}\right\} 
\end{align*}
Recall that $\e=\vect(XX^{T}-ZZ^{T})$ and $\J_{X}\vect(V)=\vect(XV^{T}+VX^{T})$
with respect to fixed $X,Z\in\R^{n\times r}$. Observe that
\[
\J_{Z}^{T}\vect(S)=0\iff(S+S^{T})Z=0\iff S=Q_{\perp}S_{\perp}Q_{\perp}^{T}\iff\vect(S)=\Q_{\perp}\vect(S_{\perp})
\]
where the orthogonal complement $Q_{\perp}$ of $Z$ is such that
$Q_{\perp}Q_{\perp}^{T}=I_{n}-ZZ^{\dagger}$, and $\Q_{\perp}=Q_{\perp}\otimes Q_{\perp}$.
Substituting and taking the Lagrangian dual yields
\begin{align}
\kappa_{\lb}(X,Z) & =\min_{\kappa,\H,s_{\perp}}\left\{ \kappa:\begin{array}{c}
I\preceq\H\preceq\kappa I,\quad s_{\perp}\in\vect(\S_{+}^{n-r^{\star}}),\quad\J_{X}^{T}(\H\e+\Q_{\perp}s_{\perp})=0,\\
2I_{r}\otimes\mat(\H\e+\Q_{\perp}s_{\perp})+\kappa\J_{X}^{T}\J_{X}\succeq0
\end{array}\right\} \nonumber \\
 & =\max_{y,W_{i,j},U,V}\left\{ \tr(U):\begin{array}{c}
\f\e^{T}+\e\f^{T}=U-V,\quad\tr(V)+\inner{\J_{X}^{T}\J_{X}}W=1,\\
\f\equiv\J_{X}y-\sum_{i=1}^{r}\vect(W_{i,i}),\quad\Q_{\perp}^{T}\f\in\vect(\S_{+}^{n-r^{\star}}),\\
U,V\succeq0,\quad W=[W_{i,j}]_{i,j=1}^{r}\succeq0
\end{array}\right\} \label{eq:ub2-1}
\end{align}
in which $y\in\R^{nr}$ and $W_{i,j}\in\R^{n\times n}$ for $i,j\in\{1,2,\dots,r\}$.
Strong duality holds here because $y=0,$ $W=\epsilon\cdot I_{nr},$
$U=\frac{1}{n}I_{n},$ and $V=\frac{1}{n}I_{n}+\epsilon\cdot r\cdot[\e\vect(I_{n})^{T}+\e\vect(I_{n})^{T}]$
is strictly feasible for a sufficiently small $\epsilon>0$. 

The dual problem (\ref{eq:ub2-1}) has a closed-form solution over
$U$ and $V$ \citep[Lemma~13]{zhang2019sharp}
\begin{align*}
\frac{\tr([M]_{-})+\alpha}{\tr([M]_{+})}= & \min_{t,U,V}\left\{ \tr(V)+\alpha\cdot t:\begin{array}{c}
tM=U-V,\quad t\ge0,\\
\tr(U)=1,\quad U,V\succeq0
\end{array}\right\} ,
\end{align*}
and $\f\e^{T}+\e\f^{T}$ has exactly two nonzero eigenvalues $\e^{T}\f\pm\|\e\|\|\f\|$
\citep[Lemma~14]{zhang2019sharp}. Substituting this solution yields
exactly 
\begin{align*}
\kappa_{\lb}(X,Z) & =\max_{y,W_{i,j}}\left\{ \frac{\|\e\|\|\f\|+\e^{T}\f}{\|\e\|\|\f\|-\e^{T}\f+\inner{\J_{X}^{T}\J_{X}}W}:\begin{array}{c}
\Q_{\perp}\Q_{\perp}^{T}\f\in\vect(\S_{+}^{n}),\\
\f=\J_{X}y-\sum_{i=1}^{r}\vect(W_{i,i}),\\
W=[W_{i,j}]_{i,j=1}^{r}\succeq0
\end{array}\right\} \\
 & =\max_{t\ge0}\frac{1+\cos\theta(t)}{2t+1-\cos\theta(t)}
\end{align*}
where $\cos\theta(t)$ is itself is defined as the following maximization
\[
\cos\theta(t)=\max_{y,W_{i,j}}\left\{ \e^{T}\f:\begin{array}{c}
\f\equiv\J_{X}y-\sum_{i=1}^{r}\vect(W_{i,i}),\quad\|\e\|\|\f\|=1,\\
(I-ZZ^{\dagger})\,\mat(\f)\,(I-ZZ^{\dagger})\succeq0,\\
\langle\J_{X}^{T}\J_{X},W\rangle=2t,\quad W=[W_{i,j}]_{i,j=1}^{r}\succeq0.
\end{array}\right\} 
\]

source_units.raw_tex:
Consider minimizing a convex objective $\phi$ over an $n\times n$
positive semidefinite matrix $M\succeq0$, as in
\begin{equation}
M^{\star}=\quad\mathrm{minimize}\quad\phi(M)\quad\text{over }\quad M\succeq0,\tag{P}\label{eq:cvx}
\end{equation}
In practice, the matrix order $n$ is often so large---from tens
of thousands to hundreds of millions---that even explicitly forming
the $n^{2}$ elements of the $n\times n$ matrix variable $M$ would
be intractable. Where $r^{\star}=\rank(M^{\star})$ is known a priori
to be small, the standard approach is the nonconvex Burer--Monteiro
factorization~\citep{burer2003nonlinear}, which rewrites $M=XX^{T}$
and then directly optimizes over $X$ using a local optimization algorithm:
\begin{equation}
X^{\star}=\quad\mathrm{minimize}\quad f(X)\eqdef\phi(XX^{T})\text{ where }X\text{ is }n\times r\text{ and }r\ge r^{\star}.\tag{BM}\label{eq:ncvx}
\end{equation}

\begin{definition}
The function $\phi:\S^{n}\to\R$ is said to be a $(\kappa,r,r^{\star})$-\emph{counterexample}
if it satisfies the following:
\begin{itemize}
\item The function $\phi$ is twice-differentiable, $L$-smooth, $\mu$-strongly
convex, and $L/\mu\le\kappa.$
\item The minimizer $M^{\star}=\arg\min_{M\succeq0}\phi(M)$ satisfies $\rank(M^{\star})=r^{\star}\le r$.
\item There exists an $n\times r$ spurious point $X$ with $XX^{T}\ne M^{\star}$
that satisfies $\nabla f(X)=0$ and $\nabla^{2}f(X)\succeq0$ for
$f(U)\eqdef\phi(UU^{T})$. 
\end{itemize}
\end{definition}

For a fixed $r$ and $r^{\star}$, our central claim in \thmref{main}
is that the condition number $\kappa^{\star}$ of the \emph{best-conditioned}
counterexample is exactly determined as 
\begin{equation}
\kappa^{\star}=\inf_{\phi:\S^{n}\to\R}\{\kappa:\phi\text{ is }(\kappa,r,r^{\star})\text{-counterexample}\}=1+2\sqrt{r/r^{\star}}.\label{eq:inf_kappa}
\end{equation}
The sufficient condition follows because there exists no $(\kappa,r,r^{\star})$-counterexample
with $\kappa<1+2\sqrt{r/r^{\star}}$, and so for a fixed $\kappa$,
we can always overparameterize $r/r^{\star}>\frac{1}{4}(\kappa-1)^{2}$
to eliminate all counterexamples. The neccessary condition holds because
a best-conditioned $(\kappa^{\star},r,r^{\star})$-counterexample
does exist.

To prove that $\kappa^{\star}$ is equal to the value stated in (\ref{eq:inf_kappa}),
we proceed by reformulating (\ref{eq:inf_kappa}) into two-stage optimization
problem 
\begin{align*}
\kappa^{\star} & =\inf_{X,Z\in\R^{n\times r}}\{\kappa(X,Z):\rank(Z)=r^{\star},\;XX^{T}\ne ZZ^{T}\}
\end{align*}
in which $\kappa(X,Z)$ corresponds to the best-conditioned counterexample
associated with a \emph{fixed} minimizer $ZZ^{T}$ and a \emph{fixed
}spurious point $X$:
\begin{equation}
\kappa(X,Z)=\inf_{\begin{subarray}{c}
\phi:\S^{n}\to\R\end{subarray}}\left\{ \kappa:\begin{array}{c}
\phi\text{ is }1\text{-strongly convex and }\kappa\text{-smooth,}\\
ZZ^{T}=\arg\min_{M\succeq0}\phi(M),\\
\nabla f(X)=0,\;\nabla^{2}f(X)\succeq0\text{ where }f(U)\eqdef\phi(UU^{T}).
\end{array}\right\} \label{eq:mu_reform}
\end{equation}

\begin{remark}
The definition of $\beta$ becomes ambiguous when $Z_{\perp}=0$.
This is without loss of precision, because $Z_{\perp}=0$ implies
$\alpha=0$, and therefore $\kappa_{\lb}(X,Z)=1$ regardless of the
value of $\beta$. 
\end{remark}

Our proof of \thmref{EckartYoung} follows a trace inequality of Ruhe~\citep{ruhe1970perturbation}
(see also \citep[Chapter~9]{marshall2011inequalities}).\footnote{This simplified proof via Ruhe's inequality is due to an anonymous
reviewer.} The inequality states that, for $n\times n$ positive semidefinite
