\begin{equation}
\sum_{i=1}^{n}\lambda_{i}(A)\lambda_{n-i+1}(B)\le\inner AB\le\sum_{i=1}^{n}\lambda_{i}(A)\lambda_{i}(B)\label{eq:Ruhe}
\end{equation}
where the eigenvalues are ordered $\lambda_{1}(A)\ge\cdots\ge\lambda_{n}(A)$
and $\lambda_{1}(B)\ge\cdots\ge\lambda_{n}(B)$.

