\begin{lemma}[Closed-form lower-bound]
\label{lem:abdef}For $X,Z\in\R^{n\times r}$ such that $XX^{T}\ne ZZ^{T}$,
let $Z_{\perp}=(I-XX^{\dagger})Z$. We have
\begin{gather*}
\kappa_{\lb}(X,Z)\ge\begin{cases}
{\displaystyle \frac{1+\sqrt{1-\alpha^{2}}}{1-\sqrt{1-\alpha^{2}}}} & \text{if }\beta\ge{\displaystyle \frac{\alpha}{1+\sqrt{1-\alpha^{2}}}},\\
{\displaystyle \frac{1-\alpha\beta}{(\alpha-\beta)\beta}} & \text{if }\beta\le{\displaystyle \frac{\alpha}{1+\sqrt{1-\alpha^{2}}}},
\end{cases}\\
\text{ where }\qquad\alpha=\frac{\|Z_{\perp}Z_{\perp}^{T}\|_{F}}{\|XX^{T}-ZZ^{T}\|_{F}},\qquad\beta=\frac{\lambda_{\min}(X^{T}X)}{\|XX^{T}-ZZ^{T}\|_{F}}{\displaystyle \frac{\tr(Z_{\perp}Z_{\perp}^{T})}{\|Z_{\perp}Z_{\perp}^{T}\|_{F}}}.
