Substituting yields the following lower-bound, which is valid for
all choices of $Y$:
\begin{align*}
\|A-YY^{T}\|_{F}^{2}+2\inner B{Y^{T}Y}= & \|A\|_{F}^{2}+\|YY^{T}\|_{F}^{2}-2\inner A{YY^{T}}+2\inner B{Y^{T}Y}\\
\ge & \sum_{i=1}^{n}s_{i}^{2}+\sum_{i=1}^{r}\sigma_{i}^{4}(Y)-2\sum_{i=1}^{r}s_{i}\sigma_{i}^{2}(Y)+2\sum_{i=1}^{r}d_{i}\sigma_{i}^{2}(Y)\\
\ge & \sum_{i=1}^{n}s_{i}^{2}-\sum_{i=1}^{r}[(s_{i}-d_{i})_{+}]^{2}.
\end{align*}
The final line applied the following result as a lower-bound:
\begin{align*}
\sigma_{i}^{4}(Y)-2(s_{i}-d_{i})\sigma_{i}^{2}(Y)\ge & \min_{x_{i}\ge0}x_{i}^{2}-2(s_{i}-d_{i})x_{i}\\
= & \min_{x_{i}\ge0}[x_{i}-(s_{i}-d_{i})]^{2}-(s_{i}-d_{i})^{2}\\
= & [(s_{i}-d_{i})_{+}-(s_{i}-d_{i})]^{2}-(s_{i}-d_{i})^{2}=-[(s_{i}-d_{i})_{+}]^{2}.
\end{align*}

Finally, we verify that $Y^{\star}=\sum_{i=1}^{n}u_{i}v_{i}\sqrt{(s_{i}-d_{i})_{+}}$
attains the lower-bound derived above. \qed
\end{proof}

\begin{lemma}
\label{lem:numcard}If $x\ge0$ and $\one^{T}x\le\|x\|^{2}$, then
$\one^{T}\left(I-xx^{T}/\|x\|^{2}\right)\one\ge\|(\one-x)_{+}\|^{2}$.
\end{lemma}

\begin{proof}
Define $u=\alpha x,$ where $\alpha=\one^{T}x/\|x\|^{2}$ is chosen
so that $\mathbf{1}^{T}u=\|u\|^{2}$. First, verify that $\mathbf{1}^{T}(I-xx^{T}/\|x\|^{2})\mathbf{1}=\|\mathbf{1}-u\|^{2}\ge\|(\mathbf{1}-u)_{+}\|^{2}$.

\begin{lemma}
\label{lem:keyclaim}Given $s,d\in\R_{+}^{n}$, let $s_{i}\ge s_{\lb}\ge0$
for all $i$. Then we have
\begin{align*}
\|s\|^{2}-\|(s-d)_{+}\|^{2}\ge & \begin{cases}
s_{\lb}^{2}\frac{(\one^{T}d)^{2}}{\|d\|^{2}} & \text{if }s_{\lb}\one^{T}d\le\|d\|^{2},\\
2s_{\lb}\one^{T}d-\|d\|^{2} & \text{if }s_{\lb}\one^{T}d\ge\|d\|^{2}.
\end{cases}
\end{align*}
\end{lemma}

\begin{proof}
First, we observe that $\psi(t)\equiv t^{2}-[(t-\alpha)_{+}]^{2}$
is an increasing function of $t\ge0$. It follows from element-wise
monotonicity that
\[
\|s\|^{2}-\|(s-d)_{+}\|^{2}\ge\|s_{\lb}\one\|^{2}-\|(s_{\lb}\one-d)_{+}\|^{2}=s_{\lb}^{2}\left(\|\one\|^{2}-\|(\one-d/s_{\lb})_{+}\|^{2}\right)
\]
If $s_{\lb}\one^{T}d\le\|d\|^{2}$, then write $x=d/s_{\lb}\ge0$,
and observe that $\one^{T}x\le\|x\|^{2}$ holds. Therefore, applying
\lemref{numcard} yields
\begin{align*}
s_{\lb}^{2}\left(\|\one\|^{2}-\|(\one-d/s_{\lb})_{+}\|^{2}\right) & =s_{\lb}^{2}\left(\|\one\|^{2}-\|(\one-x)_{+}\|^{2}\right)\ge s_{\lb}^{2}\one^{T}\left(xx^{T}/\|x\|^{2}\right)\one\\
 & =s_{\lb}^{2}\left([\one^{T}(d/s_{\lb})]^{2}/\|d/s_{\lb}\|^{2}\right)=s_{\lb}^{2}(\one^{T}d)^{2}/\|d\|^{2}.
\end{align*}
If otherwise $s_{\lb}\one^{T}d\ge\|d\|^{2}$, then we have 
\begin{align*}
s_{\lb}^{2}\left(\|\one\|^{2}-\|(\one-d/s_{\lb})_{+}\|^{2}\right)\ge s_{\lb}^{2}\left(\|\one\|^{2}-\|\one-d/s_{\lb}\|^{2}\right)=2s_{\lb}\one^{T}d-\|d\|^{2}.
\end{align*}
\qed
\end{proof}

If otherwise $s_{\lb}\one^{T}d\ge\|d\|^{2}$, then we have 
\begin{align*}
s_{\lb}^{2}\left(\|\one\|^{2}-\|(\one-d/s_{\lb})_{+}\|^{2}\right)\ge s_{\lb}^{2}\left(\|\one\|^{2}-\|\one-d/s_{\lb}\|^{2}\right)=2s_{\lb}\one^{T}d-\|d\|^{2}.
\end{align*}
\qed
\end{proof}

