\begin{lemma}
\label{lem:tradeoff}We have
\[
\kappa_{\lb}(X,Z)=\max_{t\ge0}\frac{1+\cos\theta(t)}{2t+1-\cos\theta(t)}
\]
where $\cos\theta(t)$ is defined as follows
\begin{equation}
\cos\theta(t)=\max_{y,W_{i,j}}\left\{ \e^{T}\f:\begin{array}{c}
\f\equiv\J_{X}y-\sum_{i=1}^{r}\vect(W_{i,i}),\quad\|\e\|\|\f\|=1,\\
(I-ZZ^{\dagger})\,\mat(\f)\,(I-ZZ^{\dagger})\succeq0,\\
\langle\J_{X}^{T}\J_{X},W\rangle=2t,\quad W=[W_{i,j}]_{i,j=1}^{r}\succeq0,
\end{array}\right\} \label{eq:cosprob}
\end{equation}
with respect to $y\in\R^{nr}$ and $W_{i,j}\in\R^{n\times n}$ for
$i,j\in\{1,2,\dots,r\}$.
\end{lemma}

\section{\label{app:tradeoff}Derivation of the dual for the lower-bound problem
(Proof of \lemref{tradeoff})}

We will derive the Lagrangian dual for the following
\begin{align*}
\kappa_{\lb}(X,Z) & =\min_{\kappa,\H,s}\left\{ \kappa:\begin{array}{c}
I\preceq\H\preceq\kappa I,\qquad\J_{Z}^{T}s=0,\qquad s\in\vect(\S_{+}^{n}),\\
\J_{X}^{T}(\H\e+s)=0,\quad2I_{r}\otimes\mat(\H\e+s)+\kappa\J_{X}^{T}\J_{X}\succeq0.
\end{array}\right\} 
\end{align*}
Recall that $\e=\vect(XX^{T}-ZZ^{T})$ and $\J_{X}\vect(V)=\vect(XV^{T}+VX^{T})$
with respect to fixed $X,Z\in\R^{n\times r}$. Observe that
\[
\J_{Z}^{T}\vect(S)=0\iff(S+S^{T})Z=0\iff S=Q_{\perp}S_{\perp}Q_{\perp}^{T}\iff\vect(S)=\Q_{\perp}\vect(S_{\perp})
\]
where the orthogonal complement $Q_{\perp}$ of $Z$ is such that
$Q_{\perp}Q_{\perp}^{T}=I_{n}-ZZ^{\dagger}$, and $\Q_{\perp}=Q_{\perp}\otimes Q_{\perp}$.
Substituting and taking the Lagrangian dual yields
\begin{align}
\kappa_{\lb}(X,Z) & =\min_{\kappa,\H,s_{\perp}}\left\{ \kappa:\begin{array}{c}
I\preceq\H\preceq\kappa I,\quad s_{\perp}\in\vect(\S_{+}^{n-r^{\star}}),\quad\J_{X}^{T}(\H\e+\Q_{\perp}s_{\perp})=0,\\
2I_{r}\otimes\mat(\H\e+\Q_{\perp}s_{\perp})+\kappa\J_{X}^{T}\J_{X}\succeq0
\end{array}\right\} \nonumber \\
 & =\max_{y,W_{i,j},U,V}\left\{ \tr(U):\begin{array}{c}
\f\e^{T}+\e\f^{T}=U-V,\quad\tr(V)+\inner{\J_{X}^{T}\J_{X}}W=1,\\
\f\equiv\J_{X}y-\sum_{i=1}^{r}\vect(W_{i,i}),\quad\Q_{\perp}^{T}\f\in\vect(\S_{+}^{n-r^{\star}}),\\
U,V\succeq0,\quad W=[W_{i,j}]_{i,j=1}^{r}\succeq0
\end{array}\right\} \label{eq:ub2-1}
\end{align}
in which $y\in\R^{nr}$ and $W_{i,j}\in\R^{n\times n}$ for $i,j\in\{1,2,\dots,r\}$.
Strong duality holds here because $y=0,$ $W=\epsilon\cdot I_{nr},$
$U=\frac{1}{n}I_{n},$ and $V=\frac{1}{n}I_{n}+\epsilon\cdot r\cdot[\e\vect(I_{n})^{T}+\e\vect(I_{n})^{T}]$
is strictly feasible for a sufficiently small $\epsilon>0$. 

The dual problem (\ref{eq:ub2-1}) has a closed-form solution over
$U$ and $V$ \citep[Lemma~13]{zhang2019sharp}
\begin{align*}
\frac{\tr([M]_{-})+\alpha}{\tr([M]_{+})}= & \min_{t,U,V}\left\{ \tr(V)+\alpha\cdot t:\begin{array}{c}
tM=U-V,\quad t\ge0,\\
\tr(U)=1,\quad U,V\succeq0
\end{array}\right\} ,
\end{align*}
and $\f\e^{T}+\e\f^{T}$ has exactly two nonzero eigenvalues $\e^{T}\f\pm\|\e\|\|\f\|$
\citep[Lemma~14]{zhang2019sharp}. Substituting this solution yields
exactly 
\begin{align*}
\kappa_{\lb}(X,Z) & =\max_{y,W_{i,j}}\left\{ \frac{\|\e\|\|\f\|+\e^{T}\f}{\|\e\|\|\f\|-\e^{T}\f+\inner{\J_{X}^{T}\J_{X}}W}:\begin{array}{c}
\Q_{\perp}\Q_{\perp}^{T}\f\in\vect(\S_{+}^{n}),\\
\f=\J_{X}y-\sum_{i=1}^{r}\vect(W_{i,i}),\\
W=[W_{i,j}]_{i,j=1}^{r}\succeq0
\end{array}\right\} \\
 & =\max_{t\ge0}\frac{1+\cos\theta(t)}{2t+1-\cos\theta(t)}
\end{align*}
where $\cos\theta(t)$ is itself is defined as the following maximization
\[
\cos\theta(t)=\max_{y,W_{i,j}}\left\{ \e^{T}\f:\begin{array}{c}
\f\equiv\J_{X}y-\sum_{i=1}^{r}\vect(W_{i,i}),\quad\|\e\|\|\f\|=1,\\
(I-ZZ^{\dagger})\,\mat(\f)\,(I-ZZ^{\dagger})\succeq0,\\
\langle\J_{X}^{T}\J_{X},W\rangle=2t,\quad W=[W_{i,j}]_{i,j=1}^{r}\succeq0.
\end{array}\right\} 
\]

