\begin{lemma}
\label{lem:costheta}We have $\cos\theta(t)\ge\alpha\cdot(t/\beta)+\sqrt{1-\alpha^{2}}\sqrt{1-t^{2}/\beta^{2}}$
for $0\le t\le\alpha\beta$ where $Z_{\perp}=(I-XX^{\dagger})Z$ and
\begin{align*}
\alpha & =\frac{\|Z_{\perp}Z_{\perp}^{T}\|_{F}}{\|XX^{T}-ZZ^{T}\|_{F}}, & \beta & =\frac{\lambda_{\min}(X^{T}X)\cdot\tr(Z_{\perp}Z_{\perp}^{T})}{\|XX^{T}-ZZ^{T}\|_{F}\|Z_{\perp}Z_{\perp}^{T}\|_{F}}.
\end{align*}
\end{lemma}

\begin{proof}
Write $\Pi=I-ZZ^{\dagger}$ and $\e=\vect(XX^{T}-ZZ^{T})$, and decompose
$\e_{1}=(\J_{X}\J_{X}^{\dagger})\e$ and $\e_{2}=(I-\J_{X}\J_{X}^{\dagger})\e$.
We verify that the following heuristic choice
\begin{gather*}
y=\underbrace{\frac{\sqrt{1-(t/\beta)^{2}}}{\|\e\|\|\e_{1}\|}}_{\gamma_{1}}\;\J_{X}^{\dagger}\e,\quad W=\underbrace{\frac{t/\beta}{\|\e\|\|\e_{2}\|}}_{\gamma_{2}}\;\sum_{i=1}^{r}\vect(Z_{\perp}e_{i}v_{r}^{T})\vect(Z_{\perp}e_{i}v_{r}^{T})^{T},
\end{gather*}
is feasible for (\ref{eq:cosprob}). Indeed, $W\succeq0$ holds, and
we have from (\ref{eq:e2}), (\ref{eq:Wsol1}), and (\ref{eq:Wsol2}):
\begin{gather*}
\f=\J_{X}y-\sum_{i=1}^{r}\vect(W_{i,i})=\gamma_{1}\cdot\J_{X}\J_{X}^{\dagger}\e-\gamma_{2}\vect(Z_{\perp}Z_{\perp}^{T})=\gamma_{1}\cdot\e_{1}+\gamma_{2}\e_{2},\\
\|\e\|^{2}\|\f\|^{2}=\gamma_{1}^{2}\cdot\|\e\|^{2}\|\e_{1}\|^{2}+\gamma_{2}^{2}\cdot\|\e\|^{2}\|\e_{2}\|^{2}=(1-(t/\beta)^{2})+(t/\beta)^{2}=1,\\
\langle\J_{X}^{T}\J_{X},W\rangle=2\left(\frac{t/\beta}{\|\e\|\|\e_{2}\|}\right)\cdot\lambda_{\min}(X^{T}X)\|Z_{\perp}\|_{F}^{2}=\frac{2t}{\beta}\cdot\frac{\sigma_{r}^{2}\cdot\tr(Z_{\perp}Z_{\perp}^{T})}{\|\e\|\|Z_{\perp}Z_{\perp}^{T}\|_{F}}=2t.
\end{gather*}

\begin{proof}
Write $\rho\equiv\sqrt{r/r^{\star}}$, and take $[Q_{1},Q_{2}]=I_{r+r^{\star}}$
without loss of generality. Decomposing $\e=\vect(XX^{T}-ZZ^{T})$
into eigenvectors and applying $\H$ yields
\begin{gather*}
\mat(\e)=\begin{bmatrix}I_{r} & 0\\
0 & -(1+\rho)I_{r^{\star}}
\end{bmatrix}=-\frac{1}{2\rho}\begin{bmatrix}I_{r} & 0\\
0 & \rho I_{r^{\star}}
\end{bmatrix}+\frac{1+2\rho}{2\rho}\begin{bmatrix}I_{r} & 0\\
0 & -\rho I_{r^{\star}}
\end{bmatrix},\\
\mat(\H\e)=-\frac{1+2\rho}{2\rho}\begin{bmatrix}I_{r} & 0\\
0 & \rho I_{r^{\star}}
\end{bmatrix}+\frac{1+2\rho}{2\rho}\begin{bmatrix}I_{r} & 0\\
0 & -\rho I_{r^{\star}}
\end{bmatrix}=\begin{bmatrix}0_{r} & 0\\
0 & -\kappa I_{r^{\star}}
\end{bmatrix}.
\end{gather*}
Clearly, $\inner{\mat(\e)}{\mat(\H\e)}=\kappa(1+\rho)r^{\star}.$
For $v=\vect(V)=\vect([V_{1};V_{2}])$ with $V_{1}\in\R^{r\times r}$
and $V_{2}\in\R^{r^{\star}\times r}$, observe that 
\begin{gather*}
v^{T}\J_{X}\H\e=\left\langle \begin{bmatrix}V_{1}+V_{1}^{T} & V_{2}^{T}\\
V_{2} & 0_{r^{\star}}
\end{bmatrix},\begin{bmatrix}0_{r} & 0\\
0 & -\kappa I_{r^{\star}}
\end{bmatrix}\right\rangle =0,\\
v^{T}[I_{r}\otimes\mat(\H\e)]v=\langle\mat(\H\e),VV^{T}\rangle=\left\langle \begin{bmatrix}0_{r} & 0\\
0 & -\kappa I_{r^{\star}}
\end{bmatrix},\begin{bmatrix}V_{1}V_{1}^{T} & V_{1}V_{2}^{T}\\
V_{2}V_{1}^{T} & V_{2}V_{2}^{T}
\end{bmatrix}\right\rangle =-\kappa\|V_{2}\|^{2},\\
v^{T}\J_{X}^{T}\H\J_{X}v=\left\Vert \H^{1/2}\vect\left(\begin{bmatrix}V_{1}+V_{1}^{T} & V_{2}^{T}\\
V_{2} & 0_{r^{\star}}
\end{bmatrix}\right)\right\Vert ^{2}\ge\left\Vert \H^{1/2}\vect\left(\begin{bmatrix}0_{r} & V_{2}^{T}\\
V_{2} & 0_{r^{\star}}
\end{bmatrix}\right)\right\Vert ^{2}=2\kappa\|V_{2}\|^{2}.
\end{gather*}
Therefore, $v^{T}\J_{X}\H\e=0$ and $2v^{T}[I_{r}\otimes\mat(\H\e)]v\ge-v^{T}\J_{X}^{T}\H\J_{X}v$
hold for all $v$. \qed
\end{proof}

