as a second-order critical point 
\begin{align*}
f_{0}(X)-\min_{U}f_{0}(U) & =\left(1+\frac{1}{1+\sqrt{r^{\star}/r}}\right)\frac{\|M^{\star}\|_{F}^{2}}{2}, & \nabla f_{0}(X) & =0, & \nabla^{2}f_{0}(X) & \succeq0.
\end{align*}
 \qed
