\begin{align*}
s_{i}\eqdef & \lambda_{i}(X_{1}X_{1}^{T})=\lambda_{i}(XX^{T}),\quad s_{1}\ge s_{2}\ge\cdots\ge s_{r}\ge0,\\
d_{i}\eqdef & \lambda_{i}(Z_{2}^{T}Z_{2})=\lambda_{i}(Z_{\perp}Z_{\perp}^{T}),\quad0\le d_{1}\le d_{2}\le\cdots\le d_{p}.
\end{align*}
Writing $\e=\vect(XX^{T}-ZZ^{T})$ yields
\begin{align*}
\alpha & =\frac{\|Z_{2}Z_{2}^{T}\|_{F}}{\|XX^{T}-ZZ^{T}\|_{F}}=\frac{\|d\|_{F}}{\|\e\|_{F}}, & \beta & =\frac{\lambda_{\min}(X_{1}^{T}X_{1})}{\|XX^{T}-ZZ^{T}\|_{F}}\cdot\frac{\tr(Z_{2}Z_{2}^{T})}{\|Z_{2}Z_{2}^{T}\|_{F}}=\frac{s_{r}\cdot\one^{T}d}{\|\e\|\|d\|}.
