\]
and substituting into (\ref{eq:key-claim}) yields\begin{subequations}
\begin{gather}
\beta\le\alpha\quad\implies\quad1\ge\beta^{2}+\alpha^{2}+\frac{(r-p)}{p}\beta^{2}=\alpha^{2}+\frac{r}{p}\beta^{2},\label{eq:key-claim3}\\
\beta\ge\alpha\quad\implies\quad1\ge2\alpha\beta+\frac{(r-p)}{p}\beta^{2}=\alpha^{2}+\frac{r}{p}\beta^{2}-(\beta-\alpha)^{2},\label{eq:key-claim4}
